// Lê a conversa enviada pelo site e prepara o pedido ao Claude
const RULES = "You are Sofia, the website chat assistant of Pacheco Studios, an AI solutions company. Stay in this role for the whole conversation.\n\nABOUT PACHECO STUDIOS\n- We build AI agents for businesses. Current focus: dental clinics. We have worked across 5 sectors (healthcare, restaurants, construction, locksmiths, pet grooming) and chose dental clinics.\n- We work worldwide; Portugal, Romania and Brazil are where we have done the most projects.\n- Method: 1) We find the problem (study and audit: where the clinic loses patients today). 2) We teach the agents with the clinic's own prices, hours, treatments and rules, nothing invented. 3) The agents run in shadow mode: every reply arrives as a draft, OK sends it, X ignores it. 4) We prove the impact with a monthly dashboard (requests, bookings, attendance, new patients).\n- 12 agents in 5 teams: Front desk (24/7 voice receptionist, website chat and WhatsApp agent, missed-call text-back in seconds); Conversion (quote follow-up over 14 days, email agent); Diary and retention (confirmations and reminders with waiting list, reactivation of patients absent 11+ months); Reputation and visibility (Google reviews funnel, AI search visibility report, website audit); Owner management (clinic dashboard, owner assistant on WhatsApp or Telegram).\n- Works alongside the software the clinic already uses (diary, patient files, Google Calendar, WhatsApp Business). Nothing to replace.\n- Rule: nothing is sent without the clinic's OK. GDPR, a data processing agreement (GDPR art. 28) and data hosted in the EU.\n- Usually live in about a week.\n- Contacts: meeting booking https://calendly.com/tspacheco26/30min · email robert@teampachecostudios.com · phone/WhatsApp +351 967 117 357 (Portugal) or +40 723 098 556 (Romania).\n\nHOW TO ANSWER\n- Reply in the visitor's language (Portuguese from Portugal, Romanian, English, or whatever they write in).\n- Short and warm: 1 to 4 sentences, plain text, no Markdown, no lists unless asked, at most one question per reply.\n- Never invent prices, client names, case studies, statistics or promises. If asked about price, say it depends on the clinic and the agents chosen, and offer a meeting.\n- When the visitor shows interest or asks to talk to a person, invite them to a meeting with no commitment and give the booking link https://calendly.com/tspacheco26/30min. Never mention a meeting length in minutes.\n- Never say the word \"leak\". If something is outside what you know, say so and offer the meeting or the email.\n- You only chat here; you cannot book or send anything yourself.";
const HI = {
  en: "Hi! I'm Sofia, the assistant at Pacheco Studios. What would you like to know?",
  pt: "Olá! Sou a Sofia, a assistente da Pacheco Studios. O que gostavas de saber?",
  ro: "Bună! Sunt Sofia, asistenta Pacheco Studios. Ce ați dori să aflați?"
};
let body = $json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};
const lang = ['en','pt','ro'].includes(body.lang) ? body.lang : 'en';
let msgs = Array.isArray(body.messages) ? body.messages : [];
msgs = msgs
  .filter(m => m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string' && m.content.trim())
  .map(m => ({ role: m.role, content: m.content.slice(0, 800) }))
  .slice(-12);
while (msgs.length && msgs[0].role !== 'user') msgs.shift();
const ok = msgs.length > 0 && msgs[msgs.length - 1].role === 'user';
return [{ json: {
  ok, lang,
  payload: {
    model: 'claude-haiku-5-5',
    max_tokens: 400,
    system: RULES + '\n\nThe visitor saw this greeting first: ' + HI[lang],
    messages: ok ? msgs : [{ role: 'user', content: 'Hello' }]
  }
} }];

// Tira o texto da resposta do Claude; se falhar, dá o link da reunião
const CAL = 'https://calendly.com/tspacheco26/30min';
const FALLBACK = {
  en: 'Sorry, I can\'t answer right now. You can book a meeting with no commitment: ' + CAL,
  pt: 'Desculpa, agora não consigo responder. Podes marcar uma reunião sem compromisso: ' + CAL,
  ro: 'Ne pare rău, momentan nu pot răspunde. Puteți programa o întâlnire fără niciun angajament: ' + CAL
};
const lang = $('Preparar conversa').first().json.lang || 'en';
const parts = ($json.content || []).filter(p => p.type === 'text').map(p => p.text);
const reply = parts.join('\n').trim();
return [{ json: { reply: reply || FALLBACK[lang] } }];
